func refMatch(pattern, path string) (map[string]string, bool) {
	ps := strings.Split(pattern, "/")
	xs := strings.Split(path, "/")
	out := map[string]string{}
	i := 0
	for ; i < len(ps); i++ {
		p := ps[i]
		if strings.HasPrefix(p, "*") {
			if i >= len(xs) {
				return nil, false
			}
			out[p[1:]] = "/" + strings.Join(xs[i:], "/")
			return out, true
		}
		if i >= len(xs) {
			return nil, false
		}
		if strings.HasPrefix(p, ":") {
			if xs[i] == "" && i == len(xs)-1 {
				return nil, false
			}
			out[p[1:]] = xs[i]
			continue
		}
		if p != xs[i] {
			return nil, false
		}
	}
	if i != len(xs) {
		return nil, false
	}
	return out, true
}

func kindVec(pattern string) []int {
	ps := strings.Split(pattern, "/")
	v := make([]int, 0, len(ps))
	for _, p := range ps {
		switch {
		case strings.HasPrefix(p, "*"):
			v = append(v, 2)
		case strings.HasPrefix(p, ":"):
			v = append(v, 1)
		default:
			v = append(v, 0)
		}
	}
	return v
}

func lessKind(a, b []int) bool {
	for i := 0; i < len(a) && i < len(b); i++ {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return len(a) > len(b)
}

// reference router: pick the best matching pattern
func refRoute(routes []string, path string) (string, map[string]string, bool) {
	type cand struct {
		pattern string
		params  map[string]string
	}
	var cands []cand
	for _, r := range routes {
		if ps, ok := refMatch(r, path); ok {
			cands = append(cands, cand{r, ps})
		}
	}
	if len(cands) == 0 {
		return "", nil, false
	}
	sort.SliceStable(cands, func(i, j int) bool {
		return lessKind(kindVec(cands[i].pattern), kindVec(cands[j].pattern))
	})
	return cands[0].pattern, cands[0].params, true
}

